  const ::flatbuffers::String *FEATURE_CLASS_CODE() const {
    return GetPointer<const ::flatbuffers::String *>(VT_FEATURE_CLASS_CODE);
  }
  /// The gazetteer's fine-grained feature code, verbatim.
  const ::flatbuffers::String *FEATURE_CODE() const {
    return GetPointer<const ::flatbuffers::String *>(VT_FEATURE_CODE);
  }
  /// Human-readable expansion of FEATURE_CODE, as the gazetteer publishes it.
  /// A display string, never a key.
  const ::flatbuffers::String *FEATURE_NAME() const {
    return GetPointer<const ::flatbuffers::String *>(VT_FEATURE_NAME);
  }
  /// ISO 3166-1 alpha-2 country code, uppercase, as the gazetteer states it.
  const ::flatbuffers::String *COUNTRY_CODE() const {
    return GetPointer<const ::flatbuffers::String *>(VT_COUNTRY_CODE);
  }
  /// Country name as the gazetteer publishes it. A display name, never a key:
