  /// precedence and no sovereignty claim.
  const ::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>> *ALTERNATE_COUNTRY_CODES() const {
    return GetPointer<const ::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>> *>(VT_ALTERNATE_COUNTRY_CODES);
  }
  /// First-order administrative division code within COUNTRY_CODE, verbatim.
