  builder_.add_ADMIN3_NAME(ADMIN3_NAME);
  builder_.add_ADMIN3_CODE(ADMIN3_CODE);
  builder_.add_ADMIN2_NAME(ADMIN2_NAME);
  builder_.add_ADMIN2_CODE(ADMIN2_CODE);
  builder_.add_ADMIN1_NAME(ADMIN1_NAME);
  builder_.add_ADMIN1_CODE(ADMIN1_CODE);
  builder_.add_ALTERNATE_COUNTRY_CODES(ALTERNATE_COUNTRY_CODES);
