inline const GNP *GetGNP(const void *buf) {
  return ::flatbuffers::GetRoot<GNP>(buf);
}

inline const GNP *GetSizePrefixedGNP(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<GNP>(buf);
}

inline const char *GNPIdentifier() {
  return "$GNP";
}

inline bool GNPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, GNPIdentifier());
}

inline bool SizePrefixedGNPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, GNPIdentifier(), true);
}

template <bool B = false>
inline bool VerifyGNPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<GNP>(GNPIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedGNPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<GNP>(GNPIdentifier());
}

inline void FinishGNPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<GNP> root) {
  fbb.Finish(root, GNPIdentifier());
}

inline void FinishSizePrefixedGNPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<GNP> root) {
  fbb.FinishSizePrefixed(root, GNPIdentifier());
}

